a['FormData']['ValidUntil'], 0, 16))); ?>"></div><div class="form-group col-md-4"><label>Referência do colaborador</label><input class="form-control" name="CollaboratorReference" maxlength="100" value="<?= ctr_e($data['FormData']['CollaboratorReference']); ?>"></div><div class="form-group col-md-4 pt-4"><div class="custom-control custom-checkbox"><input class="custom-control-input" id="IsIncluded" type="checkbox" name="IsIncluded" <?= ((int) $data['FormData']['IsIncluded'] === 1) ? 'checked' : ''; ?>><label class="custom-control-label" for="IsIncluded">Item incluído</label></div><div class="custom-control custom-checkbox"><input class="custom-control-input" id="IsBillable" type="checkbox" name="IsBillable" <?= ((int) $data['FormData']['IsBillable'] === 1) ? 'checked' : ''; ?>><label class="custom-control-label" for="IsBillable">Faturável</label></div></div></div><div class="form-group"><label>Atributos JSON</label><textarea class="form-control font-monospace" name="ItemAttributes" rows="4"><?= ctr_e($data['FormData']['ItemAttributes']); ?></textarea></div><div class="form-group"><label>Observações</label><textarea class="form-control" name="CustomNotes" rows="3"><?= ctr_e($data['FormData']['CustomNotes']); ?></textarea></div></fieldset><?php if (!$readonly): ?><button class="btn btn-primary" name="btnSaveItem">Salvar item</button><?php endif; ?><?php if ($data['ItemId'] !== ''): ?><span class="ml-2">Total gerado: <strong>R$ <?= ctr_money($data['FormData']['LineTotal']); ?></strong></span><?php endif; ?></form>
